/**
 * Jesus world — data contracts for the static JSON under public/jesus/.
 * words.json is generated by scripts/scriptures/extract-words.mjs from the
 * WEB USFM red-letter markup; history.json and prophecies.json are curated
 * datasets with per-item provenance.
 */

export type WordsBook = Record<string, string>;

export type WordsData = {
  /** book → "chapter:verse" → the red-letter text of that verse. */
  books: Record<string, WordsBook>;
  counts: Record<string, number>;
};

export type HistoryItem = {
  id: string;
  lane: "Jewish" | "Roman";
  author: string;
  authorNote: string;
  work: string;
  date: string;
  sourceYear: number | null;
  distance: string;
  assessment: string;
  excerpt: string;
  excerptKind?: "quotation" | "summary";
  translator: string;
  sourceUrl: string;
  note: string;
  claimsAttested: string[];
  limits: string;
};

export type ChristianWitness = {
  id: string;
  name: string;
  date: string;
  sourceYear: number;
  distance: string;
  assessment: string;
  summary: string;
  establishes: string[];
  limits: string;
  sourceUrl: string;
};

export type StoneItem = {
  id: string;
  name: string;
  found: string;
  artifactDate: string;
  inscription?: string;
  inscriptionNote?: string;
  attests: string[];
  assessment: string;
  limits: string;
  location: string;
  note: string;
  sourceUrl: string;
};

export type ProphecyPair = {
  id: string;
  theme: string;
  line: string;
  connection: "explicit" | "echo" | "typology";
  prophecy: { ref: string };
  fulfillment: { ref: string }[];
};

export type LifeEvent = {
  id: string;
  era: string;
  title: string;
  place: string;
  line: string;
  /**
   * Every passage that carries this moment. The Gospel references among them
   * are the attestation the map shows as a matrix, and each cross-Gospel pair
   * is checked by scripts/jesus/verify-attestation.mjs — two passages claimed
   * as parallels must actually share the distinctive vocabulary that parallel
   * accounts share, or the build fails.
   */
  refs: { ref: string }[];
  /**
   * True when the entry bundles distinct passages rather than one scene told
   * twice — a span of ministry, not an agreement between witnesses. Exempt
   * from the parallel check, and the page says so rather than implying the
   * Gospels corroborate each other here.
   */
  composite?: boolean;
  /**
   * Where the Gospels place this moment differently. Named rather than
   * resolved: the map takes a position, and this says what it is passing over.
   */
  orderingNote?: { note: string; refs: { ref: string }[] };
};

export type LifeData = {
  eras: { id: string; name: string }[];
  events: LifeEvent[];
};

/** Cross-to-ascension room. Each moment names which sources report it. */
export type RisenMovement = {
  id: string;
  name: string;
  window: string;
  question: string;
  line: string;
};

export type RisenMoment = {
  id: string;
  movement: string;
  clock: string;
  title: string;
  line: string;
  attestation: string;
  refs: { ref: string }[];
  /** A named difference between the accounts, shown rather than harmonized. */
  tension?: string;
};

export type RisenAppearance = {
  id: string;
  who: string;
  where: string;
  when: string;
  line: string;
  sources: { book: string; ref: string }[];
  note?: string;
};

export type RisenDescentRecord = {
  id: string;
  name: string;
  date: string;
  kind: string;
  claim: string;
  establishes: string;
  limits: string;
  sourceUrl: string;
  sourceLabel: string;
};

export type RisenOutsideCanonGroup =
  | "event-retellings"
  | "risen-dialogues"
  | "expanded-worlds";

export type RisenOutsideCanonRecord = {
  id: string;
  group: RisenOutsideCanonGroup;
  name: string;
  date: string;
  survives: string;
  kind: string;
  claim: string;
  establishes: string;
  limits: string;
  sourceUrl: string;
  sourceLabel: string;
};

export type RisenQuestion = {
  id: string;
  question: string;
  answer: string;
  refs: { ref: string }[];
};

export type RisenData = {
  movements: RisenMovement[];
  moments: RisenMoment[];
  appearances: RisenAppearance[];
  descent: RisenDescentRecord[];
  outsideCanon: RisenOutsideCanonRecord[];
  questions: RisenQuestion[];
};

export type LensExcerpt = {
  text: string;
  cite: string;
  translator: string;
  sourceUrl: string;
};

export type LensEntry = {
  id: string;
  tradition: string;
  intro: string;
  excerpts: LensExcerpt[];
  note: string;
  linkOut?: { label: string; url: string };
};

export type PerspectiveSource = {
  label: string;
  url: string;
};

export type JesusPerspective = {
  id: string;
  group: string;
  name: string;
  answer: string;
  summary: string;
  boundary: string;
  sources: PerspectiveSource[];
};

export type ArtWork = {
  id: string;
  title: string;
  culture: string;
  date: string;
  medium: string;
  artist: string;
  museum: string;
  objectUrl: string;
  /** A file on this site under /art/ — see scripts/site/vendor-museum-art.mjs. */
  imageUrl: string;
  /** The museum URL the local copy was taken from, so the vendoring stays
   *  auditable and re-runnable. */
  sourceImageUrl: string;
  license: string;
};

export type JesusEssay = {
  id: string;
  title: string;
  summary: string;
  body: string;
};

export type JesusHistorySource = {
  id: number;
  raw_title: string;
  clean_title: string;
  category: string;
  source_type: string;
  url: string;
  author: string;
  year: string;
  _load: string;
  _tier: string;
  _tier_rationale: string;
  _title_needs_fix: boolean;
};
